def _ladder(self, record, folder):
    cases = self.done_folder(record, 'cases') / 'cases.json'
    crash, status = self._call([sys.executable, STEP4 / 'stage_a/stage_a.py', '--folder', folder, '--cap', self.local_cap,
                                '--passes', self.options['passes'], '--cases-file', cases, '--shared-ledger', self.ledger_path], folder, record)
    if crash:
        return crash, status
    if status != 0:
        return 'stopped-run', f'stage_a exit {status}: a pass is incomplete (see its log)'
    conn = sqlite3.connect(f"file:{folder / 'send-1' / 'archive.sqlite'}?mode=ro", uri=True)
    try:
        found = conn.execute('select distinct config_version, config_checksum from model_calls').fetchall()
    finally:
        conn.close()
    if [f'{version} {checksum}' for version, checksum in found] != [LADDER_CONFIGURATION]:
        record['configuration mismatch'] = found
        return 'stopped-run', f'the ladder ran {found}, not the frozen {LADDER_CONFIGURATION}'
    return 'completed', None

